def basesolve(g,emit='full',stop_at_markers=True,marker_supp=False,vert_full=False):
    H,W=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cs=comps(g,bg); o=[row[:] for row in g]; dots=[]; bars=[]
    for comp in cs:
        ys=sorted({y for y,x in comp}); xs=sorted({x for y,x in comp})
        if len(comp)>3: bars.append((comp,ys,xs))
        elif len(comp)==1: dots.append(comp)
    for (comp,ys,xs) in bars:
        if emit=='full':
            if len(ys)==1:  # horizontal bar at row r
                r=ys[0]
                for c in xs:
                    # vertical beam at col c, rows between bars
                    for rr in range(H):
                        if (rr,c) in set(comp) or (rr,c) in set(dots) or g[rr][c]!=bg: continue
                        # stop at other bars
                        hit=False
                        for (bc,bys,bxs) in bars:
                            if bc is not comp and (rr,y) in set(bc) for y in bys:
                                hit=True; break
                        if hit: break
                        o[rr][c]=g[comp[0][0]][comp[0][1]] if False else g[comp[0][0]][comp[0][1]]
            else:  # vertical bar at col c
                c=xs[0]
                for rr in ys:
                    for rr2 in range(H):
                        if (rr2,c) in set(comp) or (rr2,c) in set(dots) or g[rr2][c]!=bg: continue
                        hit=False
                        for (bc,bys,bxs) in bars:
                            if bc is not comp and rr2 in bys: hit=True; break
                        if hit: break
                        o[rr2][c]=g[comp[0][0]][comp[0][1]]
        elif emit=='center':
            if len(ys)==1: r=ys[0]
            else: c=xs[0]
            pass
    return o

